package com.lexorion.payroll.service;
import static com.lexorion.payroll.api.CompensationDtos.*;import com.lexorion.payroll.api.PayrollException;import com.lexorion.payroll.domain.*;import com.lexorion.payroll.repository.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ComponentDefinitionService{private final PayrollWorkspaceScope scope;private final ComponentDefinitionRepository definitions;public ComponentDefinitionService(PayrollWorkspaceScope s,ComponentDefinitionRepository d){scope=s;definitions=d;}@Transactional(readOnly=true)public List<ComponentResponse>list(){return definitions.findByWorkspaceIdOrderByComponentKeyAsc(scope.context().workspaceId()).stream().map(ComponentResponse::from).toList();}@Transactional public ComponentResponse create(CreateComponent r){PayrollWorkspace w=scope.locked();String key=key(r.componentKey());if(definitions.existsByWorkspaceIdAndComponentKey(w.getId(),key))throw new PayrollException(409,"Compensation component already exists");ComponentDefinition d=new ComponentDefinition();d.setWorkspace(w);d.setComponentKey(key);d.setDisplayName(name(r.displayName()));d.setCategory(r.category());d.setAmountType(r.amountType());d.setOccurrenceType(r.occurrenceType());d.setTaxability(r.taxability());d.setStatus(r.status());return ComponentResponse.from(definitions.saveAndFlush(d));}@Transactional public ComponentResponse update(String raw,UpdateComponent r){scope.locked();ComponentDefinition d=find(raw);if(r.displayName()!=null)d.setDisplayName(name(r.displayName()));if(r.status()!=null)d.setStatus(r.status());return ComponentResponse.from(definitions.saveAndFlush(d));}@Transactional public ComponentResponse deactivate(String raw){scope.locked();ComponentDefinition d=find(raw);d.setStatus(ComponentStatus.INACTIVE);return ComponentResponse.from(definitions.saveAndFlush(d));}ComponentDefinition find(String raw){return definitions.findByWorkspaceIdAndComponentKey(scope.context().workspaceId(),key(raw)).orElseThrow(()->new PayrollException(404,"Compensation component not found"));}static String key(String raw){String key=raw==null?"":raw.trim().toUpperCase(Locale.ROOT);if(!key.matches("^[A-Z][A-Z0-9_]{0,63}$"))throw new PayrollException(400,"Invalid component key");return key;}static String name(String raw){String value=raw==null?"":raw.trim();if(value.isEmpty()||value.length()>150)throw new PayrollException(400,"Invalid component display name");return value;}}
